<script setup lang="ts">
import { computed, reactive,ref,watch } from 'vue'
import Icon from './Icon.vue'
import type { AppState,NetworkConfig } from './types'
const props=defineProps<{ state:AppState; busy:string }>()
const emit=defineEmits<{action:[method:string,params:Record<string,unknown>,message:string]}>()
const toForm=(config:NetworkConfig)=>({primary:config.upstreams[0].port, backup:config.upstreams[1]?.port || '', attempts:config.attempts, connect_timeout:config.connect_timeout, retry_budget:config.retry_budget, keepalive_idle:config.keepalive_idle, keepalive_interval:config.keepalive_interval, terminal_environment:config.terminal_environment,route_strategy:config.route_strategy || 'adaptive',race_delay_ms:config.race_delay_ms || 150})
const form=reactive(toForm(props.state.config)),baseline=ref(JSON.stringify(form))
const dirty=computed(()=>JSON.stringify(form)!==baseline.value)
watch(()=>props.state.config,config=>{const values=toForm(config),saved=JSON.stringify(values);if(!dirty.value || saved===JSON.stringify(form)){Object.assign(form,values);baseline.value=saved}})
function reset(){Object.assign(form,toForm(props.state.config));baseline.value=JSON.stringify(form)}
const locked=computed(()=>props.state.system.owned || props.state.operation.running || !!props.busy || props.state.network?.measure?.running)
const kernelWritable=computed(()=>props.state.kernel.available && !props.state.kernel.running && !props.busy)
function save(){ const {primary,backup,...rest}=form; const upstreams=[{host:'127.0.0.1',port:Number(primary)}]; if(backup!=='')upstreams.push({host:'127.0.0.1',port:Number(backup)}); emit('action','network.configure',{config:{...rest,upstreams}},'传输策略已保存，下一条新连接将使用新策略。') }
const fields=[{key:'attempts' as const,label:'最多尝试次数',min:1,max:8,unit:'次'},{key:'connect_timeout' as const,label:'单次连接超时',min:2,max:15,unit:'秒'},{key:'retry_budget' as const,label:'总重试预算',min:5,max:90,unit:'秒'},{key:'keepalive_idle' as const,label:'空闲保活等待',min:30,max:300,unit:'秒'},{key:'keepalive_interval' as const,label:'保活探测间隔',min:10,max:60,unit:'秒'},{key:'race_delay_ms' as const,label:'第二入口错峰等待',min:50,max:500,unit:'ms'}]
</script>
<template><div class="workspace-page">
  <div v-if="state.system.owned" class="notice neutral"><Icon name="info"/><span>网络优化正在运行。请先关闭优化，再修改连接策略。</span></div>
  <div v-if="dirty" class="notice neutral"><Icon name="info"/><span>表单包含未保存修改。</span><button class="text-button" @click="reset">恢复已保存参数</button></div>
  <form @submit.prevent="save"><fieldset :disabled="locked"><div class="settings-grid"><section class="panel"><div class="section-heading"><div><span class="eyebrow muted">LOCAL UPSTREAM</span><h3>本地代理入口</h3><p>连接已在本机运行的 HTTP／mixed 代理。</p></div><span class="section-icon"><Icon name="globe"/></span></div><label class="field-label" for="primary-port">主代理端口<span>127.0.0.1</span></label><div class="input-with-prefix"><span>PORT</span><input id="primary-port" v-model.number="form.primary" type="number" min="1" max="65535" required></div><label class="field-label spaced" for="backup-port">备用代理端口<span>可选</span></label><div class="input-with-prefix"><span>PORT</span><input id="backup-port" v-model.number="form.backup" type="number" min="1" max="65535" placeholder="不使用备用代理"></div><p class="micro-copy">主代理建连失败时，再尝试备用入口。两个端口应来自可用的本地代理。</p></section><section class="panel"><div class="section-heading"><div><span class="eyebrow muted">RETRY & KEEPALIVE</span><h3>连接恢复与保活</h3><p>只恢复隧道建立前的连接，不重放请求。</p></div><span class="section-icon"><Icon name="refresh"/></span></div><label class="field-label" for="route-strategy">上游选择策略<select id="route-strategy" v-model="form.route_strategy"><option value="adaptive">自适应：近期观测优先</option><option value="race">错峰竞速：较快入口优先</option><option value="ordered">按配置顺序</option></select></label><div class="form-grid"><label v-for="field in fields" :key="field.key" class="field-label">{{ field.label }}<div class="number-input"><input v-model.number="form[field.key]" type="number" :min="field.min" :max="field.max" required><span>{{ field.unit }}</span></div><small>{{ field.min }}–{{ field.max }} {{ field.unit }}</small></label></div></section></div><section class="panel environment-panel"><div><h3>终端代理环境</h3><p>可选：为之后启动、遵循代理环境变量的终端程序设置代理。</p><span class="micro-copy">关闭网络优化时，恢复本工具接管前的值。</span></div><label class="native-switch"><input v-model="form.terminal_environment" type="checkbox"><span class="switch-visual"><i></i></span><span class="sr-only">为终端设置代理环境变量</span></label></section><div class="form-footer"><span><Icon name="shield" :size="15"/>原设置会在接管前保存</span><button class="btn primary" type="submit"><Icon name="check" :size="17"/>保存传输策略</button></div></fieldset></form>
  <section class="panel kernel-panel"><div class="section-heading"><div><span class="eyebrow muted">PROXY KERNEL</span><h3>FlClash 内核保活</h3><p>{{ state.kernel.available ? state.kernel.running ? 'FlClash 正在运行，请完全退出后再保存内核设置。' : '已识别本地配置，可以保存或恢复保活设置。' : '尚未识别到兼容的 FlClash 配置。' }}</p></div><span class="section-icon"><Icon name="settings"/></span></div><div v-if="state.kernel.available" class="kernel-values"><span>保活间隔<strong>{{ state.kernel.keepalive }} 秒</strong></span><span>切换策略时主动断开<strong>{{ state.kernel.close_connections ? '开启' : '关闭' }}</strong></span></div><div class="button-row"><button class="btn secondary" :disabled="!kernelWritable" @click="emit('action','kernel.apply',{},'FlClash 保活设置已保存。')">保存保活设置</button><button class="btn ghost" :disabled="!kernelWritable" @click="emit('action','kernel.restore',{},'已恢复原 FlClash 保活设置。')">恢复原设置</button></div></section>
</div></template>
